import{_ as t,C as l,o as n,c as o,a3 as e,b as u,w as i,a as s,E as m,a4 as k}from"./chunks/framework.BvvarXmc.js";const d="/screenshots/kantin-menus.png",P=JSON.parse('{"title":"Manajemen Menu & Cetak Barcode","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-kantin/daftar-menu.md","filePath":"panduan-kantin/daftar-menu.md","lastUpdated":null}'),g={name:"panduan-kantin/daftar-menu.md"};function p(h,a,b,c,M,f){const r=l("Mermaid");return n(),o("div",null,[a[1]||(a[1]=e('<h1 id="manajemen-menu-cetak-barcode" tabindex="-1">Manajemen Menu &amp; Cetak Barcode <a class="header-anchor" href="#manajemen-menu-cetak-barcode" aria-label="Permalink to &quot;Manajemen Menu &amp; Cetak Barcode&quot;">​</a></h1><p>Halaman <strong>Daftar Menu</strong> digunakan oleh pengelola kantin dan koperasi untuk mengatur seluruh katalog produk yang dijual, menetapkan harga jual dan harga modal (HPP), mengontrol sisa stok, mencetak lembar barcode produk, hingga mengimpor menu secara massal melalui file Excel.</p><p>Menu ini dapat diakses melalui <strong>Kantin</strong> &gt; <strong>Menu</strong> pada sidebar aplikasi.</p><hr><h2 id="tampilan-halaman-daftar-menu" tabindex="-1">Tampilan Halaman Daftar Menu <a class="header-anchor" href="#tampilan-halaman-daftar-menu" aria-label="Permalink to &quot;Tampilan Halaman Daftar Menu&quot;">​</a></h2><p>Berikut adalah tampilan antarmuka manajemen menu kantin sekolah:</p><p><img src="'+d+'" alt="Daftar Menu Kantin"></p><hr><h2 id="_1-alur-menambahkan-menu-makanan-minuman-baru" tabindex="-1">1. Alur Menambahkan Menu Makanan / Minuman Baru <a class="header-anchor" href="#_1-alur-menambahkan-menu-makanan-minuman-baru" aria-label="Permalink to &quot;1. Alur Menambahkan Menu Makanan / Minuman Baru&quot;">​</a></h2>',9)),(n(),u(k,null,{default:i(()=>[m(r,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20Klik%20'%2B%20Tambah%20Menu'%22%5D%20--%3E%20B%5B%222.%20Unggah%20Foto%20%26%20Isi%20Data%20Produk%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Tentukan%20Harga%20Jual%20%26%20HPP%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Pilih%20Sifat%20Barang%20%26%20Supplier%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20Simpan%20Menu%20(Muncul%20di%20Kasir)%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="langkah-langkah" tabindex="-1">Langkah-langkah: <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah:&quot;">​</a></h3><ol><li>Klik tombol <strong><code>+ Tambah Menu</code></strong> berwarna ungu di pojok kanan atas tabel.</li><li>Jendela modal formulir produk akan terbuka. Isi kolom-kolom berikut: <ul><li><strong>Foto Menu</strong>: Unggah foto produk makanan/minuman yang menarik (format JPG/PNG, maks 2MB) agar kasir dan siswa mudah mengenali produk.</li><li><strong>Nama Menu</strong> <em>(Wajib)</em>: Masukkan nama lengkap menu (contoh: <em>Donat Madu</em>, <em>Nasi Uduk Ayam</em>, <em>Es Teh Manis</em>).</li><li><strong>Kategori</strong> <em>(Wajib)</em>: Pilih kelompok kategori yang sesuai (misal: <em>Gorengan</em>, <em>Makanan Berat</em>, <em>Minuman Dingin</em>, <em>Snack Kemasan</em>).</li><li><strong>Harga Jual</strong> <em>(Wajib)</em>: Harga nominal yang harus dibayar oleh siswa (contoh: <em>Rp 5.000</em>).</li><li><strong>Harga Pokok / HPP (Harga Modal)</strong>: Biaya modal per porsi untuk keperluan kalkulasi laba bersih kantin dan bagi hasil supplier.</li><li><strong>Sifat Barang</strong>: <ul><li><strong>Harian</strong>: Makanan basah atau olahan cepat basi yang habis dalam satu hari (misal: gorengan, nasi bungkus, jajanan pasar). Makanan ini akan dihitung retur saat tutup buku sore hari.</li><li><strong>Tahan Lama</strong>: Produk kemasan pabrik yang tidak basi dalam sehari (misal: biskuit, air mineral kemasan, pulpen, buku tulis).</li></ul></li><li><strong>Jumlah Stok Awal</strong>: Masukkan kuantiti stok yang tersedia saat ini di etalase kantin.</li><li><strong>Jenis Kepemilikan &amp; Supplier</strong>: <ul><li><em>Produk Mandiri</em>: Makanan yang diproduksi dan dijual langsung oleh pihak kantin sekolah.</li><li><em>Konsinyasi (Titip Jual)</em>: Makanan yang dititipkan oleh pedagang/mitra luar (pilih nama supplier dari daftar mitra).</li></ul></li></ul></li><li>Klik tombol <strong>Simpan Menu</strong>. Menu baru seketika aktif dan siap dipilih pada layar kasir POS.</li></ol><hr><h2 id="_2-alur-mengedit-memperbarui-menu" tabindex="-1">2. Alur Mengedit &amp; Memperbarui Menu <a class="header-anchor" href="#_2-alur-mengedit-memperbarui-menu" aria-label="Permalink to &quot;2. Alur Mengedit &amp; Memperbarui Menu&quot;">​</a></h2><ol><li>Cari menu yang ingin diubah pada tabel produk menggunakan kolom pencarian atau filter kategori.</li><li>Pada kolom paling kanan (<strong>Aksi</strong>), klik <strong>Ikon Edit (Pensil)</strong>.</li><li>Ubah harga, perbarui foto, atau sesuaikan jumlah stok yang tersedia.</li><li>Klik <strong>Perbarui Menu</strong>. Perubahan harga akan langsung berlaku saat transaksi kasir berikutnya.</li></ol><hr><h2 id="_3-fitur-cetak-lembar-barcode-print-barcode-sheet" tabindex="-1">3. Fitur Cetak Lembar Barcode (<em>Print Barcode Sheet</em>) <a class="header-anchor" href="#_3-fitur-cetak-lembar-barcode-print-barcode-sheet" aria-label="Permalink to &quot;3. Fitur Cetak Lembar Barcode (*Print Barcode Sheet*)&quot;">​</a></h2><p>Fitur ini sangat bermanfaat bagi stan kantin yang ingin mempercepat proses antrean menggunakan alat barcode scanner USB:</p><ol><li>Di atas tabel menu, klik tombol <strong><code>Cetak Barcode</code></strong>.</li><li>Modal pratinjau lembar barcode akan terbuka menampilkan seluruh barcode produk yang tersusun rapi per baris dan kolom.</li><li>Anda dapat memilih opsi pencetakan: <ul><li><strong>Lembar Kertas Stiker</strong>: Dicetak pada kertas stiker untuk ditempel langsung pada bungkus makanan atau wadah etalase.</li><li><strong>Lembar Meja Kasir (Laminating)</strong>: Dicetak pada selembar kertas HVS/karton untuk diletakkan di samping meja kasir. Kasir cukup mengarahkan scanner ke kode barcode di lembaran tersebut tanpa perlu mengetik nama menu.</li></ul></li><li>Klik tombol <strong>Cetak Sekarang (Print)</strong>.</li></ol><hr><h2 id="_4-fitur-impor-menu-massal-dari-excel" tabindex="-1">4. Fitur Impor Menu Massal dari Excel <a class="header-anchor" href="#_4-fitur-impor-menu-massal-dari-excel" aria-label="Permalink to &quot;4. Fitur Impor Menu Massal dari Excel&quot;">​</a></h2><p>Jika kantin memiliki puluhan hingga ratusan jenis produk baru di awal tahun ajaran, Anda dapat memasukkannya sekaligus menggunakan file Excel:</p><ol><li>Klik tombol <strong><code>Import Excel</code></strong> berwarna hijau di atas tabel.</li><li>Unduh <strong>Template Excel (.xlsx)</strong> resmi yang disediakan oleh sistem.</li><li>Buka template tersebut dan isi data produk mengikuti susunan kolom yang ditentukan (Nama Menu, Kategori, Harga Jual, Harga Pokok, Sifat Barang, Stok Awal).</li><li>Simpan file Excel, lalu unggah kembali file ke dalam jendela modal impor.</li><li>Klik <strong>Mulai Impor</strong>. Sistem akan memvalidasi data dan seluruh menu akan terdaftar secara otomatis tanpa perlu input manual satu per satu.</li></ol>',13))])}const B=t(g,[["render",p]]);export{P as __pageData,B as default};
